using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithPromptsFromAssembly()
    .WithResourcesFromAssembly();

var app = builder.Build();
app.MapMcp();                      // exposes MCP endpoint at /mcp (Streamable HTTP)
app.MapGet("/health", () => "ok"); // health check for container orchestrators
app.Run();

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns current application configuration data.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };
        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/version", Name = "App Version",
        MimeType = "text/plain"),
     Description("Returns the application version string.")]
    public static string GetVersion() => "1.0.0";
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g., 'MaxRetries', 'TimeoutSeconds')")] string key)
    {
        var settings = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
        {
            ["Environment"] = "production",
            ["MaxRetries"] = 3,
            ["TimeoutSeconds"] = 30,
            ["DarkMode"] = true,
            ["BetaAccess"] = false
        };

        return settings.TryGetValue(key, out var value)
            ? JsonSerializer.Serialize(new { key, value })
            : JsonSerializer.Serialize(new { key, error = "Key not found" });
    }

    [McpServerTool, Description("Validate whether a configuration key exists and has a non-null value.")]
    public static string ValidateConfig(
        [Description("Comma-separated list of configuration keys to validate")] string keys)
    {
        var knownKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "Environment", "MaxRetries", "TimeoutSeconds", "DarkMode", "BetaAccess"
        };

        var results = keys.Split(',', StringSplitOptions.TrimEntries)
            .Select(k => new { Key = k, Valid = knownKeys.Contains(k) })
            .ToList();

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

